# ---------------------------------------------------------------- Finance and markets
L.append({"id": "finance-and-markets", "title": "Finance and markets", "band": "Business", "minutes": 32,
 "lede": "The words traders, bankers and business owners use every day. Know them exactly, because in money, a vague definition costs real dollars.",
 "sections": [
  T("## Why precision matters here\nIn everyday talk, *margin*, *equity* and *liquidity* are fuzzy. In finance each one has an exact meaning, and some words have **two** meanings depending on context. Mixing them up is how people misread a contract, a broker statement or a prop-firm rule."),
  TERMS([
   ("asset", "Something you **own** that has value: cash, a truck, a trading account."),
   ("liability", "Something you **owe**: a truck loan, a credit card balance."),
   ("equity", "(1) **Ownership value** = assets − liabilities. (2) In a trading account, the current value including open trades."),
   ("liquidity", "How easily something turns into **cash** without moving its price. Cash is perfectly liquid; a house isn't. A liquid market has lots of buyers and sellers."),
   ("leverage", "Using borrowed money or a small deposit to control a **larger** position. Multiplies gains **and** losses."),
   ("margin (futures)", "A **good-faith deposit** required to hold a futures position. Not a down payment and not a loan."),
   ("margin (business)", "Profit as a **percent of revenue**: profit ÷ revenue."),
   ("volatility", "How much and how fast a price moves. High volatility = big swings."),
   ("bid / ask / spread", "**Bid**: the highest price a buyer will pay now. **Ask**: the lowest price a seller will take. **Spread**: the gap between them."),
   ("bull / bear", "**Bull**: expecting prices to rise (or a rising market). **Bear**: expecting a fall."),
   ("hedge", "A position taken to **reduce** risk from another position, like insurance."),
   ("diversification", "Spreading money across different assets so one loss can't sink everything."),
   ("drawdown", "The drop from an account's **peak** to its lowest point after it."),
   ("slippage", "The difference between the price you **expected** and the price you **got**, common in fast markets and with market orders."),
  ], label="The core terms"),
  T("## The balance sheet idea\nEvery business and every person has the same equation underneath:\n\n**Assets − Liabilities = Equity (net worth)**\n\n| You have | Value |\n|---|---|\n| Truck (asset) | $85,000 |\n| Cash (asset) | $6,000 |\n| Truck loan (liability) | −$62,000 |\n| **Equity** | **$29,000** |\n\nA nice truck isn't wealth if the loan is almost as big. Equity is what's actually **yours**."),
  CHECK("You own a $40,000 truck with a $35,000 loan and have $2,000 cash. Your equity is…", ["$42,000", "$7,000", "$5,000", "$40,000"], 1, "Assets $42,000 − liabilities $35,000 = **$7,000**."),
  T("## Leverage in futures\nOne **NQ** (E-mini Nasdaq-100) contract moves **$20 per index point**. One **MNQ** (Micro) moves **$2 per point**, one-tenth the size. The smallest price move, a **tick**, is 0.25 points: **$5** on NQ, **$0.50** on MNQ.\n\nThe index level changes daily, but at **25,000** points, one NQ contract controls **$500,000** of index exposure (25,000 × $20). A trader can hold that with a margin deposit that's a small fraction of it. That's **leverage**.\n\n*A 50-point move against one NQ contract = 50 × $20 = $1,000.* On a $50,000 account, that's 2% from one ordinary swing. This is why position size, not entry, decides whether a trader survives."),
  E("Drawdown math", "An account goes from $50,000 up to a peak of $53,000, then falls to $50,350.",
    ["Drawdown = peak − low = 53,000 − 50,350 = 2,650.", "As a percent of the peak: 2,650 ÷ 53,000 ≈ 5%."],
    "**$2,650, about 5%.** Measured from the **peak**, not the starting balance. Prop firms track this exactly, often as a trailing limit that follows your highest balance."),
  T("## Liquidity and the spread\nIn a **liquid** market (NQ during New York hours), the spread is usually one tick and big orders fill near the expected price. In an **illiquid** market (a thinly traded penny stock, or futures in a quiet overnight session), spreads widen and **slippage** grows.\n\nRule of thumb: the less liquid the market, the more an order **moves the price against you**."),
  CHECK("Bid is 20,100.00, ask is 20,100.25 on NQ. The spread is…", ["0 points", "0.25 points (1 tick, $5 per contract)", "1 point", "$20"], 1, "Ask − bid = 0.25 = one tick."),
  N("Common traps", "- **Futures margin isn't borrowing** (unlike stock margin, which is a loan from the broker). It's collateral.\n- **Equity has two meanings.** Ownership value, and the live value of a trading account.\n- **Leverage cuts both ways.** It's not free money; it's magnified risk.\n- **Drawdown is from the peak.** Not from where you started.")
 ],
 "practice": [
  MC("A truck loan is a(n)…", ["asset", "liability", "equity", "hedge"], 1, "Something you owe."),
  MC("Which is most **liquid**?", ["a house", "cash", "a semi truck", "a collectible watch"], 1, "Already cash."),
  NUM("One MNQ contract: how many dollars per index point?", 2, "MNQ = $2/point. NQ = $20.", unit="$"),
  NUM("A 30-point move on 1 NQ contract is worth how many dollars?", 600, "30 × $20.", unit="$"),
  MC("The **spread** is…", ["your profit", "the gap between bid and ask", "the daily range", "the margin"], 1, "Ask − bid."),
  MC("Getting filled at a worse price than expected is…", ["slippage", "leverage", "a hedge", "liquidity"], 0, "Common with market orders in fast moves."),
  MC("A **bear** expects prices to…", ["rise", "fall", "stay flat", "double"], 1, "Bears swipe down."),
  NUM("Revenue $10,000, profit $1,500. Profit margin (%)?", 15, "1,500 ÷ 10,000 = 15%.", unit="%"),
  NUM("Account peaks at $52,400, then drops to $50,900. Drawdown in dollars?", 1500,
      "52,400 − 50,900 = **$1,500**, measured from the peak.",
      level="challenge", hint="Peak minus the low after it.", unit="$"),
  NUM("You trade 15 MNQ contracts. How many dollars per point is that?", 30,
      "15 × $2 = **$30 per point**, 1.5× one NQ. A 10-point stop = $300 risk.",
      level="challenge", hint="Multiply contracts by $2.", unit="$"),
  MC("A farmer sells wheat futures in spring to lock in a price for her fall harvest. She's…", ["speculating", "hedging", "diversifying", "leveraging up"], 1,
     "She's reducing price risk on wheat she already grows. Hedging is the original reason futures markets exist.",
     level="challenge", hint="Is she taking on risk or reducing it?"),
  MC("Why does slippage tend to grow in the overnight session?", ["Prices are higher at night", "Fewer buyers and sellers → wider spreads, thinner order book", "Exchanges charge more", "Leverage changes"], 1,
     "Lower liquidity means each order moves price more.",
     level="challenge", hint="Think about liquidity."),
 ],
 "sources": [CFTC, INV, {"title": "CME Group: Micro E-mini Nasdaq-100 futures contract specs", "url": "https://www.cmegroup.com/markets/equities/nasdaq/micro-e-mini-nasdaq-100.contractSpecs.html"}]})

# ---------------------------------------------------------------- Contracts and negotiation
L.append({"id": "contracts-and-negotiation", "title": "Contracts and negotiation", "band": "Business", "minutes": 32,
 "lede": "The words in rate confirmations, broker agreements, leases and sponsorship deals. Read them right, and you know what you're agreeing to before you sign.",
 "sections": [
  T("## Read before you sign\nA contract is enforceable whether or not you understood it. Most costly business mistakes aren't bad deals. They're **unread clauses**. This lesson covers the words that show up most, in general contracts and in freight specifically.\n\n*(This is vocabulary, not legal advice. For a big contract, have a lawyer read it.)*"),
  TERMS([
   ("party", "A person or company that's part of the contract."),
   ("terms", "The specific conditions everyone agrees to: price, dates, duties."),
   ("clause", "One section or provision of a contract."),
   ("consideration", "What each side gives to make the deal binding: money, a service, a promise."),
   ("breach", "Failing to do what the contract requires."),
   ("liability", "(legal) Being **legally responsible** for something, like damage or debt."),
   ("indemnify", "To **cover someone else's losses** or legal costs. *Carrier shall indemnify Broker* = you pay if they get sued over your actions."),
   ("force majeure", "French for *superior force*: a clause excusing a party when something outside their control (disaster, war) prevents performance."),
   ("net 30", "Payment due **30 days** after the invoice."),
   ("accounts receivable / payable", "**Receivable**: money owed **to** you. **Payable**: money **you** owe."),
   ("factoring", "Selling your unpaid invoices to a company that pays you most of the amount **now**, for a fee."),
   ("leverage (negotiation)", "Whatever gives you power in a negotiation: options, timing, unique value."),
  ], label="General terms"),
  TERMS([
   ("shipper / consignee", "**Shipper**: who sends the freight. **Consignee**: who receives it."),
   ("broker", "A middleman who arranges freight between shippers and carriers, keeping a margin."),
   ("rate confirmation (rate con)", "The written agreement for one load: rate, pickup, delivery, terms. Effectively the contract."),
   ("bill of lading (BOL)", "The shipping document describing the freight. It's a receipt and a contract of carriage."),
   ("proof of delivery (POD)", "The signed document showing the freight was delivered. You usually need it to get paid."),
   ("detention", "Pay for waiting beyond the **free time** (often 2 hours) at pickup or delivery."),
   ("lumper", "A worker paid to load or unload a truck. The fee is usually reimbursed with a receipt."),
   ("accessorials", "Extra charges beyond the line-haul rate: detention, lumper, layover, TONU, extra stops."),
   ("TONU", "*Truck Ordered, Not Used*: a fee when a load is canceled after the carrier was dispatched."),
  ], label="Freight terms"),
  CHECK("A broker's agreement says the carrier must **indemnify** the broker for cargo damage claims. That means…", ["the broker pays you if cargo is damaged", "you cover the broker's losses if they're sued over damage", "nobody is responsible", "the shipper pays"], 1, "Indemnify = cover someone else's losses."),
  T("## Clauses to always find\nBefore signing any rate con or agreement, find these:\n\n| Clause | What to check |\n|---|---|\n| **Rate** | the all-in amount, and whether fuel is included |\n| **Payment terms** | net 30? net 45? quick-pay fee? |\n| **Detention** | when it starts (after how many hours) and the hourly rate |\n| **Accessorials** | lumper reimbursement, layover, TONU |\n| **Cancellation** | what happens if they cancel after you're dispatched |\n| **Fines / deductions** | late fees, missing-paperwork penalties |\n| **Indemnification / liability** | what you're on the hook for |\n| **Back-solicitation** | many broker agreements bar you from working directly with their shipper for a period |\n\nIf something isn't written, assume you **won't** get it."),
  E("Read a rate con line", "*\"Rate: $1,850 all-in. Payment net 30, quick pay 3%. Detention $50/hr after 2 hrs, must be reported within 1 hr of departure with in/out times.\"*",
    ["$1,850 **all-in**: no separate fuel surcharge.", "Net 30: paid about a month after you invoice. Quick pay: paid faster for 3%, which is $55.50 on this load.", "Detention starts at hour 3, $50/hr, **but** only if you report it within an hour, with timestamps. Miss the report and you likely lose it."],
    "The detention condition is the trap. The money is there **only** if you follow the reporting rule."),
  T("## Cash flow words\n- **Invoice**: your bill for a completed load.\n- **Net 30** means waiting about a month for money you've already earned, while you pay fuel today.\n- **Factoring** solves that: the factor pays you, say, 97% now and collects the full invoice later. The 3% fee is the price of speed.\n- **Quick pay**: the broker's own version, paying faster for a percentage.\n\n**Recourse vs non-recourse factoring:** with *recourse*, if the broker never pays, **you** owe the money back. *Non-recourse* shifts more of that risk to the factor, at a higher fee. (Read which risks it actually covers.)"),
  CHECK("You factor a $2,000 invoice at a 3% fee. You receive…", ["$2,000", "$1,940", "$60", "$2,060"], 1, "2,000 × 0.97 = **$1,940**. The factor keeps $60."),
  N("Common traps", "- **Signing the rate con without reading the fine print.** Detention and fine clauses live there.\n- **Verbal promises.** *We'll take care of you on detention* means nothing unless it's written.\n- **Missing paperwork.** No signed POD, no payment, often.\n- **Liability (legal) vs liability (accounting).** Same word: one is legal responsibility, one is a debt.")
 ],
 "practice": [
  MC("The receiver of a shipment is the…", ["shipper", "consignee", "broker", "lumper"], 1, "Shipper sends, consignee receives."),
  MC("Pay for waiting past free time is…", ["TONU", "detention", "factoring", "consideration"], 1, "Usually after 2 hours."),
  MC("**Net 30** means…", ["30% down payment", "payment due 30 days after invoice", "30 loads minimum", "a 30% fee"], 1, "Payment terms."),
  MC("Money owed **to** your business is…", ["accounts payable", "accounts receivable", "liability", "equity"], 1, "Receivable = to receive."),
  MC("A **breach** is…", ["a payment", "failing to meet the contract's terms", "a type of truck", "a bonus"], 1, "Breaking the agreement."),
  MC("The document you usually need signed to get paid after delivery is the…", ["BOL only", "POD (proof of delivery)", "TONU", "invoice"], 1, "Proof the job was done."),
  MC("A load is canceled after you've driven to the shipper. The fee you'd claim is…", ["detention", "TONU", "lumper", "factoring"], 1, "Truck Ordered, Not Used."),
  MC("**Force majeure** clauses cover…", ["late payments", "events outside anyone's control, like disasters", "fuel prices", "driver mistakes"], 1, "\"Superior force.\""),
  NUM("You factor a $3,200 invoice at 2.5%. How much do you receive now?", 3120,
      "3,200 × 0.975 = **$3,120**. Fee: $80.",
      level="challenge", hint="Keep 97.5%.", unit="$"),
  NUM("Detention: $50/hr starting after 2 free hours. You wait 5.5 hours total. Detention owed?", 175,
      "Billable = 5.5 − 2 = 3.5 hrs × $50 = **$175**, if you reported it as the rate con requires.",
      level="challenge", hint="Subtract the free time first.", unit="$"),
  MC("Your rate con says \"$2,000 all-in.\" The broker later says fuel surcharge wasn't included. Who's right?", ["The broker", "The rate con: *all-in* means everything, including fuel, is in the $2,000", "Nobody", "It depends on fuel prices"], 1,
     "All-in = one total. That's also why you should check whether the rate is all-in **before** signing: you can't add fuel later.",
     level="challenge", hint="What does all-in mean?"),
  MC("With **recourse** factoring, if the broker never pays the invoice…", ["the factor eats the loss", "you may have to pay the advance back to the factor", "the shipper pays", "the government pays"], 1,
     "Recourse = the risk comes back to you. Non-recourse shifts some of that risk to the factor for a higher fee.",
     level="challenge", hint="Recourse = it can come back to you."),
 ],
 "sources": [MW, SBA, {"title": "FMCSA: Broker Registration", "url": "https://www.fmcsa.dot.gov/registration/broker-registration"}]})

# ---------------------------------------------------------------- Management and operations
L.append({"id": "management-and-operations", "title": "Management and operations", "band": "Business", "minutes": 32,
 "lede": "The language of running a business that grows: costs, break-even, cash flow, KPIs, bottlenecks and systems. Know these and you can read any business book, pitch any lender, and run your trucks like a company.",
 "sections": [
  T("## Revenue isn't profit\nThe single most important idea in business vocabulary:\n\n- **Revenue** (or *gross income*, *top line*): all money coming in.\n- **Gross profit**: revenue minus the **direct** costs of doing the work (fuel, tolls, driver pay).\n- **Net profit** (*bottom line*): what's left after **all** costs, including overhead, interest and taxes.\n\nA truck that grosses $20,000 a month can still **lose** money. The bottom line is the only line that pays you."),
  TERMS([
   ("fixed costs", "Costs that **stay the same** no matter how much you work: truck payment, insurance, phone plan."),
   ("variable costs", "Costs that **rise with activity**: fuel, tolls, tires, maintenance per mile."),
   ("overhead", "Ongoing costs of running the business that don't tie to one job: insurance, software, accounting, office."),
   ("break-even point", "The level of sales where revenue exactly covers all costs: zero profit, zero loss."),
   ("cash flow", "The **timing** of money in and out. A profitable business can still fail if cash comes in too late."),
   ("ROI (return on investment)", "Gain ÷ cost. How much an investment earns relative to what it cost."),
   ("KPI (key performance indicator)", "One of the few numbers you track to know if the business is healthy."),
   ("utilization", "How much of your capacity you actually use. A truck sitting idle is low utilization."),
   ("bottleneck", "The slowest step in a process, which limits everything else."),
   ("SOP (standard operating procedure)", "A written, step-by-step way to do a recurring task the same way every time."),
   ("scalable", "Able to grow without costs or effort growing just as fast."),
   ("contingency plan", "A plan B, prepared in advance, for when something goes wrong."),
  ], label="The core terms"),
  T("## Break-even, step by step\n**Break-even** = fixed costs ÷ (price per unit − variable cost per unit)\n\nThe bottom part, **price − variable cost**, is the **contribution margin**: what each unit (each mile, each load) contributes toward paying the fixed costs.\n\n*Example:* fixed costs are **$6,000 a month** (truck note, insurance, permits, phone). You earn **$2.30 per mile**, and variable costs are **$0.80 per mile** (fuel, maintenance, tolls).\n\n- Contribution per mile: 2.30 − 0.80 = **$1.50**\n- Break-even: 6,000 ÷ 1.50 = **4,000 miles a month**\n\nEvery mile below 4,000 loses money. Every mile above it is profit. That one number tells you how many loads you **must** book each month."),
  CHECK("A business has $3,000 in monthly fixed costs and makes $5 contribution per unit. Break-even is…", ["300 units", "600 units", "15,000 units", "$600"], 1, "3,000 ÷ 5 = 600."),
  T("## KPIs: the dashboard\nA KPI is a number that tells you the truth fast. A good business tracks **a few**, every week:\n\n| KPI | Trucking example | Trading example |\n|---|---|---|\n| revenue per mile / per trade | revenue ÷ total miles | average P&L per trade |\n| cost per mile / per trade | all costs ÷ miles | commissions and fees |\n| utilization | % of days the truck is loaded | % of sessions with an A+ setup traded |\n| quality | on-time %, claims | % of trades that followed the plan |\n| risk | deadhead % | max drawdown |\n\n*What gets measured gets managed* is a business cliché because it works. Pick the few numbers that matter, and look at them every week."),
  E("ROI decision", "An APU (auxiliary power unit) costs $9,000 installed. It saves about $300 a month in idle fuel. What's the payback period and first-year ROI?",
    ["Payback: 9,000 ÷ 300 = 30 months (2.5 years).", "First-year savings: 300 × 12 = 3,600.", "First-year ROI: (3,600 − 9,000) ÷ 9,000 = −60%: it hasn't paid for itself yet.", "Over 5 years: 18,000 saved vs 9,000 cost → ROI = 100%."],
    "**ROI depends on the time frame.** Worth it if you'll keep the truck long enough; a bad buy if you'll sell it next year."),
  T("## Systems that let you grow\n- **SOPs** turn what's in your head into steps someone else can follow. You can't hire a dispatcher or a second driver until the job is written down.\n- **Bottlenecks** limit everything. If you can only check load boards when you're not driving, **you** are the bottleneck, not the truck.\n- **Scalable** work grows without your hours growing at the same rate. One truck you drive yourself isn't very scalable. A dispatch system serving five trucks is more scalable.\n- **Contingency plans** are written **before** the crisis: breakdown, canceled load, a slow freight month. (A trading plan's daily loss limit is a contingency plan.)"),
  CHECK("You can't grow past two trucks because you personally book every load. You are the…", ["KPI", "bottleneck", "overhead", "consignee"], 1, "The slowest step limiting the whole system."),
  N("Common traps", "- **Revenue ≠ profit.** Always ask: what's left after **all** costs?\n- **Profitable ≠ cash rich.** Net 30 payments can starve a profitable business of cash.\n- **Too many KPIs.** Tracking 30 numbers is tracking none. Pick 3–5.\n- **Forgetting fixed costs** when pricing a load. Each load must contribute its share of the truck note and insurance.")
 ],
 "practice": [
  MC("The bottom line is…", ["revenue", "net profit", "gross revenue", "cash on hand"], 1, "What's left after all costs."),
  MC("Fuel is a ___ cost for a truck.", ["fixed", "variable", "overhead only", "sunk"], 1, "It rises with miles."),
  MC("Insurance paid monthly regardless of miles is a ___ cost.", ["fixed", "variable", "contribution", "marginal"], 0, "Doesn't change with activity."),
  NUM("Fixed costs $4,500/month. Contribution $1.50 per mile. Break-even miles?", 3000, "4,500 ÷ 1.50 = 3,000.", unit="miles"),
  NUM("Invest $2,000, gain $500 profit. ROI (%)?", 25, "500 ÷ 2,000 = 25%.", unit="%"),
  MC("A written step-by-step process for recurring tasks is an…", ["ROI", "SOP", "KPI", "APU"], 1, "Standard operating procedure."),
  MC("A business can be profitable on paper and still run out of money because of…", ["too much revenue", "cash flow timing", "low fixed costs", "too many KPIs"], 1, "Money earned isn't money received."),
  MC("A truck loaded 18 of 22 working days has a utilization of about…", ["18%", "82%", "22%", "50%"], 1, "18 ÷ 22 ≈ 82%."),
  NUM("Fixed costs $6,000/month. Rate $2.40/mile, variable costs $0.90/mile. Break-even miles per month?", 4000,
      "Contribution = 2.40 − 0.90 = $1.50. 6,000 ÷ 1.50 = **4,000 miles**.",
      level="challenge", hint="Find the contribution per mile first.", unit="miles"),
  NUM("Same truck: you drive 9,000 miles this month. Profit?", 7500,
      "Miles above break-even: 9,000 − 4,000 = 5,000. × $1.50 = **$7,500**. (Check: revenue 21,600 − variable 8,100 − fixed 6,000 = 7,500 ✓.)",
      level="challenge", hint="Every mile past break-even earns the contribution.", unit="$"),
  NUM("A $12,000 upgrade saves $400/month. Payback period in months?", 30,
      "12,000 ÷ 400 = **30 months**.",
      level="challenge", hint="Cost ÷ monthly savings.", unit="months"),
  MC("Which KPI set is best for a one-truck owner-operator?", ["Instagram followers, mood, weather", "Revenue per total mile, cost per mile, deadhead %, on-time %", "30 different metrics updated hourly", "Only total revenue"], 1,
     "A few numbers that show profit, efficiency and service quality. Revenue alone hides costs; 30 metrics hide everything.",
     level="challenge", hint="Few, and tied to profit and quality."),
 ],
 "sources": [SBA, {"title": "SBA: Break-even point", "url": "https://www.sba.gov/business-guide/plan-your-business/calculate-your-startup-costs/break-even-point"}]})

save("vocab", L)
